import Foundation

/// One generated file, relative to the export folder (for example "framework/enrollment.sh").
struct GeneratedFile: Equatable {
    let path: String
    let contents: Data
    let isExecutable: Bool
}

/// An installer package copied into framework/installers/ when the framework is written to disk.
struct InstallerCopy {
    let path: String
    let source: InstallerSource
    let sha256: String
}

struct GeneratedFramework {
    let rootName: String
    let files: [GeneratedFile]
    let installerCopies: [InstallerCopy]
    let taskCount: Int

    func file(at path: String) -> GeneratedFile? {
        files.first { $0.path == path }
    }

    func text(at path: String) -> String? {
        file(at: path).map { String(decoding: $0.contents, as: UTF8.self) }
    }

    var allPaths: [String] {
        (files.map { $0.path } + installerCopies.map { $0.path }).sorted()
    }
}

enum FrameworkGeneratorError: LocalizedError, Equatable {
    case noTasks
    case invalidTaskIdentifier(String)
    case invalidBundleIdentifier(String)
    case missingAsset(String)
    case missingInstaller(String)

    var errorDescription: String? {
        switch self {
        case .noTasks:
            return "The project has no enabled tasks to generate."
        case .invalidTaskIdentifier(let id):
            return "The task identifier \"\(id)\" contains characters the framework does not accept."
        case .invalidBundleIdentifier(let id):
            return "The bundle identifier \"\(id)\" is not a valid reverse-DNS identifier."
        case .missingAsset(let path):
            return "The project file \(path) is missing."
        case .missingInstaller(let path):
            return "The installer package \(path) is missing from the project."
        }
    }
}

/// Turns a project into the enrollment framework. Pure: it reads only the values passed in, so tests can
/// inspect every generated byte. Writing to disk is FrameworkExporter's job.
///
/// Export layout:
///   framework/            installed to the project's install location
///     enrollment.sh  uninstall.sh  VERSION
///     config/enrollment.conf  config/dialog.json  config/tasks.json
///     lib/*.sh  tasks/NNN-<task id>.sh  icons/  scripts/  installers/
///   launchd/<label>.plist  installed to /Library/LaunchDaemons
///   package-scripts/preinstall  package-scripts/postinstall
///   README.txt
enum FrameworkGenerator {
    static let frameworkDirectory = "framework"
    static let maxParallel = 4
    static let detectionInterval = 10
    static let dialogWaitTimeout = 600
    static let logDirectory = "/Library/Logs/Microsoft/IntuneScripts/onBoarding"
    /// Placeholder for the framework's own folder in dialog.json; replaced on the device by lib/dialog.sh.
    static let installDirectoryToken = "__INSTALL_DIR__"

    static func rootName(for project: EnrollmentProject) -> String {
        let name = FilenameSanitizer.sanitize(project.settings.packageDisplayName, fallback: "EnrollmentBundle")
        return "\(name)-\(project.settings.packageVersion)-framework"
    }

    static func generate(
        project: EnrollmentProject,
        assets: [String: Data],
        installerSources: [String: InstallerSource],
        now: Date = Date()
    ) throws -> GeneratedFramework {
        let settings = project.settings
        // It names the LaunchDaemon and its property list, so never let an invalid value reach a file name.
        guard FieldValidator.isValidReverseDNS(settings.bundleIdentifier) else {
            throw FrameworkGeneratorError.invalidBundleIdentifier(settings.bundleIdentifier)
        }
        let installDirectory = trimmedDirectory(settings.installLocation)
        let plan = TaskPlanner.plan(project)
        let analysis = DependencyGraph.analyze(plan)

        var byID: [String: PlannedTask] = [:]
        for task in plan where byID[task.taskIdentifier] == nil {
            byID[task.taskIdentifier] = task
        }
        let ordered = analysis.orderedTaskIDs.compactMap { byID[$0] }
        guard !ordered.isEmpty else { throw FrameworkGeneratorError.noTasks }
        for task in ordered where !isValidTaskIdentifier(task.taskIdentifier) {
            throw FrameworkGeneratorError.invalidTaskIdentifier(task.taskIdentifier)
        }
        let enabledIDs = Set(ordered.map { $0.taskIdentifier })
        var batchNumber: [String: Int] = [:]
        for (index, batch) in analysis.batches.enumerated() {
            for id in batch { batchNumber[id] = index + 1 }
        }

        var files: [GeneratedFile] = []
        func add(_ path: String, _ text: String, executable: Bool = false) {
            let normalized = text.hasSuffix("\n") ? text : text + "\n"
            files.append(GeneratedFile(path: path, contents: Data(normalized.utf8), isExecutable: executable))
        }
        func addData(_ path: String, _ data: Data, executable: Bool = false) {
            files.append(GeneratedFile(path: path, contents: data, isExecutable: executable))
        }
        let framework = frameworkDirectory

        // Fixed framework files.
        for template in FrameworkTemplates.staticFiles {
            add("\(framework)/\(template.path)", template.contents, executable: template.isExecutable)
        }

        // Images used by the dialog.
        var imagePaths: [String] = []
        if let logo = project.branding.logoPath { imagePaths.append(logo) }
        if let banner = project.branding.bannerPath { imagePaths.append(banner) }
        if let overlay = project.branding.overlayIconPath { imagePaths.append(overlay) }
        for application in project.allApplications where application.isEnabled && application.icon.kind == .projectAsset {
            imagePaths.append(application.icon.value)
        }
        for task in project.systemTasks where task.icon.kind == .projectAsset {
            imagePaths.append(task.icon.value)
        }
        for path in Set(imagePaths).sorted() {
            guard let data = assets[path] else { throw FrameworkGeneratorError.missingAsset(path) }
            addData("\(framework)/\(iconRelativePath(for: path))", data)
        }
        // The desktop wallpaper travels inside the framework and is copied to /Library/Desktop Pictures on the device.
        if let wallpaper = project.branding.wallpaperPath {
            guard let data = assets[wallpaper] else { throw FrameworkGeneratorError.missingAsset(wallpaper) }
            addData("\(framework)/\(wallpaperRelativePath(project: project, assetPath: wallpaper))", data)
        }
        // Resolved by lib/dialog.sh to the folder the framework runs from, so images always match the files.
        func deviceIcon(_ assetPath: String) -> String {
            "\(installDirectoryToken)/\(iconRelativePath(for: assetPath))"
        }
        func iconValue(_ icon: IconSource, _ applicationPath: String) -> String {
            switch icon.kind {
            case .applicationBundle: return applicationPath.isEmpty ? "SF=app.dashed" : applicationPath
            case .projectAsset: return deviceIcon(icon.value)
            case .sfSymbol: return "SF=\(icon.value)"
            }
        }

        // Dialog list and configuration.
        let entries = DialogConfigBuilder.listEntries(project: project, iconPath: iconValue)
        var listPosition: [String: (index: Int, isSummary: Bool)] = [:]
        for entry in entries {
            for id in entry.taskIdentifiers { listPosition[id] = (entry.index, entry.isSummary) }
        }
        let dialog = DialogConfigBuilder.configuration(
            project: project,
            entries: entries,
            totalTasks: ordered.count,
            logoPath: project.branding.logoPath.map(deviceIcon),
            bannerPath: project.branding.bannerPath.map(deviceIcon),
            overlayIconPath: project.branding.overlayIconPath.map(deviceIcon),
            resolve: PlaceholderResolver.normalizingTokens
        )
        addData("\(framework)/config/dialog.json", try DialogConfigBuilder.jsonData(dialog))

        // Task files, scripts and installers.
        let width = max(3, String(ordered.count * 10).count)
        var summaries: [TaskSummary] = []
        var installerCopies: [InstallerCopy] = []
        for (offset, task) in ordered.enumerated() {
            let number = String(format: "%0\(width)d", (offset + 1) * 10)
            let fileName = "\(number)-\(task.taskIdentifier).sh"
            let slot = listPosition[task.taskIdentifier]
            var lines = taskHeader(task)
            lines.append(ShellQuoting.assignment("TASK_ID", task.taskIdentifier))
            lines.append(ShellQuoting.assignment("TASK_NAME", task.displayName))
            lines.append(ShellQuoting.assignment("TASK_REQUIRED", task.isRequired))
            lines.append(ShellQuoting.assignment("TASK_VISIBLE", slot != nil))
            lines.append(ShellQuoting.assignment("TASK_LIST_INDEX", slot?.index ?? -1))
            lines.append(ShellQuoting.assignment("TASK_LIST_SUMMARY", slot?.isSummary ?? false))
            lines.append(ShellQuoting.assignment("TASK_CONTEXT", task.execution.context.rawValue))
            lines.append(ShellQuoting.assignment("TASK_TIMEOUT", task.execution.timeoutSeconds))
            lines.append(ShellQuoting.assignment("TASK_RETRIES", task.execution.retryCount))
            let dependencies = task.allDependencies.filter { enabledIDs.contains($0) }
            lines.append(ShellQuoting.assignment("TASK_DEPENDS", dependencies.joined(separator: " ")))
            lines.append(ShellQuoting.assignment("TASK_BATCH", batchNumber[task.taskIdentifier] ?? 0))
            lines.append(ShellQuoting.assignment("TASK_PARALLEL_GROUP", task.execution.parallelGroup))
            lines.append(ShellQuoting.assignment("TASK_ALLOW_SKIP", task.execution.allowSkip))
            lines.append(ShellQuoting.assignment("TASK_ALLOW_RERUN", task.execution.allowRerun))
            let messages = task.execution.messages
            lines.append(ShellQuoting.assignment("TASK_MSG_WAITING", messages.waiting))
            lines.append(ShellQuoting.assignment("TASK_MSG_PROGRESS", messages.progress))
            lines.append(ShellQuoting.assignment("TASK_MSG_SUCCESS", messages.success))
            lines.append(ShellQuoting.assignment("TASK_MSG_WARNING", messages.warning))
            lines.append(ShellQuoting.assignment("TASK_MSG_FAILURE", messages.failure))

            var typeName = task.type.rawValue
            switch task.source {
            case .application(let id):
                guard let application = project.application(id: id) else { continue }
                var installerPath = ""
                var installerHash = ""
                if application.installStrategy == .bundledInstaller, let installer = application.installer {
                    guard let source = installerSources[installer.relativePath] else {
                        throw FrameworkGeneratorError.missingInstaller(installer.relativePath)
                    }
                    let name = (installer.relativePath as NSString).lastPathComponent
                    installerPath = "installers/\(name)"
                    installerHash = installer.sha256
                    installerCopies.append(InstallerCopy(path: "\(framework)/\(installerPath)", source: source, sha256: installer.sha256))
                    typeName = TaskType.packageInstallation.rawValue
                } else {
                    // Without an attached package every application strategy is detected like Wait for Intune.
                    typeName = TaskType.applicationDetection.rawValue
                }
                lines.append(ShellQuoting.assignment("TASK_TYPE", typeName))
                lines.append(ShellQuoting.assignment("TASK_STRATEGY", application.installStrategy.rawValue))
                lines.append(ShellQuoting.assignment("TASK_APP_PATH", application.applicationPath))
                lines.append(ShellQuoting.assignment("TASK_BUNDLE_ID", application.bundleIdentifier))
                lines.append(ShellQuoting.assignment("TASK_PROCESS_NAME", application.processName))
                lines.append(ShellQuoting.assignment("TASK_DETECTION", application.detection.method.rawValue))
                lines.append(ShellQuoting.assignment("TASK_DETECTION_VALUE", application.detection.value))
                lines.append(ShellQuoting.assignment("TASK_INSTALLER", installerPath))
                lines.append(ShellQuoting.assignment("TASK_INSTALLER_SHA256", installerHash))
                // "Run custom script": the linked script runs first, then the app is detected (see run_app_script_task).
                if let script = TaskPlanner.linkedScript(of: application, in: project) {
                    guard let data = assets[script.relativePath] else { throw FrameworkGeneratorError.missingAsset(script.relativePath) }
                    let name = (script.relativePath as NSString).lastPathComponent
                    addData("\(framework)/scripts/\(name)", data, executable: true)
                    lines.append(ShellQuoting.assignment("TASK_SCRIPT", "scripts/\(name)"))
                    lines.append(ShellQuoting.assignment("TASK_SUCCESS_CODES", script.successExitCodes.map(String.init).joined(separator: " ")))
                }
            case .script(let id):
                guard let script = project.script(id: id) else { continue }
                guard let data = assets[script.relativePath] else { throw FrameworkGeneratorError.missingAsset(script.relativePath) }
                let name = (script.relativePath as NSString).lastPathComponent
                addData("\(framework)/scripts/\(name)", data, executable: true)
                lines.append(ShellQuoting.assignment("TASK_TYPE", TaskType.shellScript.rawValue))
                lines.append(ShellQuoting.assignment("TASK_SCRIPT", "scripts/\(name)"))
                lines.append(ShellQuoting.assignment("TASK_SUCCESS_CODES", script.successExitCodes.map(String.init).joined(separator: " ")))
            case .system(let id):
                guard let system = project.systemTask(id: id) else { continue }
                lines.append(ShellQuoting.assignment("TASK_TYPE", system.type.rawValue))
                lines.append(ShellQuoting.assignment("TASK_VALIDATION_VALUE", system.validation?.value ?? ""))
            }
            add("\(framework)/tasks/\(fileName)", lines.joined(separator: "\n"))
            summaries.append(TaskSummary(
                file: "tasks/\(fileName)",
                id: task.taskIdentifier,
                name: task.displayName,
                type: typeName,
                required: task.isRequired,
                listIndex: slot?.index,
                context: task.execution.context.rawValue,
                timeoutSeconds: task.execution.timeoutSeconds,
                retries: task.execution.retryCount,
                dependsOn: dependencies,
                batch: batchNumber[task.taskIdentifier] ?? 0,
                parallelGroup: task.execution.parallelGroup
            ))
        }

        add("\(framework)/config/enrollment.conf", configurationFile(project: project, installDirectory: installDirectory, now: now))
        addData("\(framework)/config/tasks.json", try tasksJSON(summaries))
        add("\(framework)/VERSION", versionFile(project: project, now: now))
        addData("launchd/\(settings.bundleIdentifier).plist", try launchDaemon(project: project, installDirectory: installDirectory))
        add("package-scripts/preinstall", packageScript(FrameworkTemplates.preinstallScript, project: project, installDirectory: installDirectory), executable: true)
        add("package-scripts/postinstall", packageScript(FrameworkTemplates.postinstallScript, project: project, installDirectory: installDirectory), executable: true)
        for file in try detectionAppFiles(project: project) {
            files.append(file)
        }
        add("\(intuneDirectory)/\(intunePreInstallFileName)", intunePreInstallScript(project: project), executable: true)
        add("README.txt", readme(project: project, installDirectory: installDirectory))

        return GeneratedFramework(
            rootName: rootName(for: project),
            files: files.sorted { $0.path < $1.path },
            installerCopies: installerCopies,
            taskCount: ordered.count
        )
    }

    // MARK: Pieces

    struct TaskSummary: Codable, Equatable {
        let file: String
        let id: String
        let name: String
        let type: String
        let required: Bool
        let listIndex: Int?
        let context: String
        let timeoutSeconds: Int
        let retries: Int
        let dependsOn: [String]
        let batch: Int
        let parallelGroup: String
    }

    /// Lowercase ASCII letters, digits, dots and hyphens, starting with a letter or digit (as task-runner.sh checks).
    static func isValidTaskIdentifier(_ id: String) -> Bool {
        guard let first = id.unicodeScalars.first, first != ".", first != "-" else { return false }
        return id.unicodeScalars.allSatisfy { scalar in
            (scalar >= "a" && scalar <= "z") || (scalar >= "0" && scalar <= "9") || scalar == "." || scalar == "-"
        }
    }

    /// Branding images get a prefix so they cannot collide with application icons.
    static func iconRelativePath(for assetPath: String) -> String {
        let name = (assetPath as NSString).lastPathComponent
        if assetPath.hasPrefix("\(ProjectLayout.brandingDirectory)/") {
            return "icons/branding-\(name)"
        }
        return "icons/\(name)"
    }

    /// Folder on the device where the wallpaper is placed so it outlives the framework (uninstall.sh keeps it).
    static let wallpaperDeviceDirectory = "/Library/Desktop Pictures"

    /// File name for the wallpaper, for example "Contoso-Wallpaper.jpg". Used inside the framework and on the device.
    static func wallpaperFileName(project: EnrollmentProject, assetPath: String) -> String {
        let base = FilenameSanitizer.sanitize("\(project.settings.organizationName) Wallpaper", fallback: "Corporate-Wallpaper")
        let pathExtension = (assetPath as NSString).pathExtension.lowercased()
        return "\(base).\(pathExtension.isEmpty ? "jpg" : pathExtension)"
    }

    static func wallpaperRelativePath(project: EnrollmentProject, assetPath: String) -> String {
        "wallpaper/\(wallpaperFileName(project: project, assetPath: assetPath))"
    }

    static func trimmedDirectory(_ path: String) -> String {
        var result = path
        while result.count > 1 && result.hasSuffix("/") {
            result.removeLast()
        }
        return result
    }

    private static func taskHeader(_ task: PlannedTask) -> [String] {
        [
            "#!/bin/bash",
            "# \(oneLineComment(task.displayName)) (\(task.taskIdentifier))",
            "# Generated by Enrollment Bundle Studio \(AppInfo.version). Data only: loaded by lib/task-runner.sh, never executed."
        ]
    }

    private static func oneLineComment(_ text: String) -> String {
        text.replacingOccurrences(of: "\n", with: " ").replacingOccurrences(of: "\r", with: " ")
    }

    static func configurationFile(project: EnrollmentProject, installDirectory: String, now: Date) -> String {
        let settings = project.settings
        let branding = project.branding
        let normalize = PlaceholderResolver.normalizingTokens
        var lines = [
            "# Generated by Enrollment Bundle Studio \(AppInfo.version) on \(ISO8601DateFormatter().string(from: now)).",
            "# Regenerate from the project instead of editing. Sourced by enrollment.sh and uninstall.sh.",
            ShellQuoting.assignment("appname", "onBoarding"),
            ShellQuoting.assignment("project_id", project.id.uuidString),
            ShellQuoting.assignment("project_name", settings.projectName),
            ShellQuoting.assignment("organization_name", settings.organizationName),
            ShellQuoting.assignment("bundle_identifier", settings.bundleIdentifier),
            ShellQuoting.assignment("bundle_version", settings.packageVersion),
            ShellQuoting.assignment("package_version", settings.packageVersion),
            ShellQuoting.assignment("launchd_label", settings.bundleIdentifier),
            ShellQuoting.assignment("install_dir", installDirectory),
            ShellQuoting.assignment("state_dir", trimmedDirectory(settings.stateDirectory)),
            ShellQuoting.assignment("dialog_path", settings.swiftDialogPath),
            ShellQuoting.assignment("dialog_min_version", settings.swiftDialogMinimumVersion),
            ShellQuoting.assignment("lock_button", settings.lockCompletionButtonUntilRequiredComplete),
            ShellQuoting.assignment("max_duration", settings.maximumEnrollmentDurationSeconds),
            ShellQuoting.assignment("max_parallel", maxParallel),
            ShellQuoting.assignment("detection_interval", detectionInterval),
            ShellQuoting.assignment("user_wait_timeout", settings.maximumEnrollmentDurationSeconds),
            ShellQuoting.assignment("dialog_wait_timeout", dialogWaitTimeout),
            ShellQuoting.assignment("debug_logging", settings.debugLogging),
            ShellQuoting.assignment("onboarding_flag", settings.onboardingFlagPath),
            ShellQuoting.assignment("enrollment_window_hours", settings.enrollmentWindowHours),
            ShellQuoting.assignment("button_text", branding.buttonText),
            ShellQuoting.assignment("completion_command", branding.completionCommand.trimmingCharacters(in: .whitespacesAndNewlines)),
            ShellQuoting.assignment("completion_command_as_user", branding.completionCommandRunsAsUser),
            ShellQuoting.assignment("completion_icon", "SF=\(branding.completionSymbol)"),
            ShellQuoting.assignment("msg_welcome", normalize(branding.welcomeMessage)),
            ShellQuoting.assignment("msg_completion", normalize(branding.completionMessage)),
            ShellQuoting.assignment("msg_warning", normalize(branding.warningMessage)),
            ShellQuoting.assignment("msg_failure", normalize(branding.failureMessage))
        ]
        if let wallpaper = branding.wallpaperPath {
            lines.append(ShellQuoting.assignment("wallpaper_source", wallpaperRelativePath(project: project, assetPath: wallpaper)))
            lines.append(ShellQuoting.assignment("wallpaper_target",
                                                 "\(wallpaperDeviceDirectory)/\(wallpaperFileName(project: project, assetPath: wallpaper))"))
        }
        if let dock = project.dock, dock.isEnabled {
            let items = dock.resolvedItems(in: project)
            lines.append(ShellQuoting.assignment("dock_enabled", true))
            lines.append(ShellQuoting.assignment("dock_remove_default", dock.removeDefaultItems))
            lines.append(ShellQuoting.assignment("dock_position", dock.position.rawValue))
            lines.append(ShellQuoting.assignment("dock_tile_size", min(max(dock.tileSize, DockConfiguration.tileSizeRange.lowerBound), DockConfiguration.tileSizeRange.upperBound)))
            lines.append(ShellQuoting.assignment("dock_autohide", dock.autoHide))
            lines.append(ShellQuoting.assignment("dock_fingerprint", dock.fingerprint(in: project)))
            lines.append(ShellQuoting.assignment("dock_item_count", items.count))
            for (index, item) in items.enumerated() {
                lines.append(ShellQuoting.assignment("dock_item_\(index + 1)_label", item.label))
                lines.append(ShellQuoting.assignment("dock_item_\(index + 1)_path", item.path))
            }
        }
        lines.append(ShellQuoting.assignment("detection_app", detectionApp(project: project).path))
        lines.append("")
        return lines.joined(separator: "\n")
    }

    static func tasksJSON(_ summaries: [TaskSummary]) throws -> Data {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]
        var data = try encoder.encode(summaries)
        data.append(0x0A)
        return data
    }

    static func versionFile(project: EnrollmentProject, now: Date) -> String {
        [
            "bundle_version=\(project.settings.packageVersion)",
            "package_version=\(project.settings.packageVersion)",
            "package_identifier=\(project.settings.packageIdentifier)",
            "project_id=\(project.id.uuidString)",
            "generated=\(ISO8601DateFormatter().string(from: now))",
            "generator=Enrollment Bundle Studio \(AppInfo.version)"
        ].joined(separator: "\n")
    }

    static func launchDaemon(project: EnrollmentProject, installDirectory: String) throws -> Data {
        let plist: [String: Any] = [
            "Label": project.settings.bundleIdentifier,
            "ProgramArguments": ["/bin/bash", "\(installDirectory)/enrollment.sh"],
            "RunAtLoad": true,
            "AbandonProcessGroup": true,
            "StandardOutPath": "\(logDirectory)/launchd.log",
            "StandardErrorPath": "\(logDirectory)/launchd.log"
        ]
        return try PropertyListSerialization.data(fromPropertyList: plist, format: .xml, options: 0)
    }

    // MARK: Detection placeholder app

    /// Export folder with the detection placeholder app; the package builder places it on the device.
    static let detectionDirectory = "detection"
    static let detectionExecutableName = "marker"

    /// Name, device folder and full path of the placeholder app Intune detects.
    struct DetectionApp: Equatable {
        let name: String
        let directory: String
        var path: String { directory == "/" ? "/\(name)" : "\(directory)/\(name)" }
    }

    static func detectionApp(project: EnrollmentProject) -> DetectionApp {
        let organization = project.settings.organizationName.trimmingCharacters(in: .whitespacesAndNewlines)
        let base = organization.isEmpty ? "Enrollment Bundle" : "\(organization) Bundle"
        let configured = (project.settings.detectionAppDirectory ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let directory = configured.isEmpty ? project.settings.installLocation : configured
        return DetectionApp(name: FilenameSanitizer.sanitize(base, fallback: "Enrollment-Bundle") + ".app",
                            directory: trimmedDirectory(directory))
    }

    /// A small app bundle (Info.plist and an executable that does nothing) whose bundle identifier and version are
    /// the package's. The package contains no other app, so Intune uses this one to see that the package is installed.
    static func detectionAppFiles(project: EnrollmentProject) throws -> [GeneratedFile] {
        let app = detectionApp(project: project)
        let settings = project.settings
        let name = (app.name as NSString).deletingPathExtension
        let plist: [String: Any] = [
            "CFBundleIdentifier": settings.packageIdentifier,
            "CFBundleName": name,
            "CFBundleDisplayName": name,
            "CFBundleShortVersionString": settings.packageVersion,
            "CFBundleVersion": settings.packageVersion,
            "CFBundleExecutable": detectionExecutableName,
            "CFBundlePackageType": "APPL",
            "CFBundleInfoDictionaryVersion": "6.0",
            "LSMinimumSystemVersion": settings.minimumMacOSVersion,
            "LSUIElement": true,
            "LSBackgroundOnly": true
        ]
        let data = try PropertyListSerialization.data(fromPropertyList: plist, format: .xml, options: 0)
        let root = "\(detectionDirectory)/\(app.name)/Contents"
        return [
            GeneratedFile(path: "\(root)/Info.plist", contents: data, isExecutable: false),
            GeneratedFile(path: "\(root)/MacOS/\(detectionExecutableName)",
                          contents: Data("#!/bin/sh\n# Placeholder so Intune can detect the enrollment package. It does nothing.\nexit 0\n".utf8),
                          isExecutable: true)
        ]
    }

    /// Export folder holding files that are not part of the installer package but are used when deploying it.
    static let intuneDirectory = "intune"
    static let intunePreInstallFileName = "pre-install.sh"

    /// The Intune pre-install script for this project: skips the install on Macs that already have the onboarding flag.
    static func intunePreInstallScript(project: EnrollmentProject) -> String {
        FrameworkTemplates.intunePreInstallScript
            .replacingOccurrences(of: "__ONBOARDING_FLAG__", with: ShellQuoting.singleQuoted(project.settings.onboardingFlagPath))
    }

    static func packageScript(_ template: String, project: EnrollmentProject, installDirectory: String) -> String {
        template
            .replacingOccurrences(of: "__LAUNCHD_LABEL__", with: ShellQuoting.singleQuoted(project.settings.bundleIdentifier))
            .replacingOccurrences(of: "__INSTALL_DIR__", with: ShellQuoting.singleQuoted(installDirectory))
    }


    static func readme(project: EnrollmentProject, installDirectory: String) -> String {
        let label = project.settings.bundleIdentifier
        return """
        \(project.settings.projectName): generated enrollment framework
        Generated by Enrollment Bundle Studio \(AppInfo.version). Bundle version \(project.settings.packageVersion), package version \(project.settings.packageVersion).

        Layout
          framework/         installs to \(installDirectory)
          launchd/           \(label).plist installs to /Library/LaunchDaemons
          package-scripts/   preinstall and postinstall for the installer package
          detection/         placeholder app that Intune detects; installs to \(detectionApp(project: project).directory)
          intune/            pre-install.sh for the Intune app's Pre-install script setting (not in the package)

        Package Builder builds these files into an unsigned flat installer package. To test by hand on a
        test Mac, open Terminal in this folder (the one containing this README) and run:
          sudo mkdir -p "\(installDirectory)"
          sudo cp -R framework/. "\(installDirectory)/"
          sudo chown -R root:wheel "\(installDirectory)"
          sudo chmod -R go-w "\(installDirectory)"
          sudo "\(installDirectory)/enrollment.sh" --dry-run
          sudo "\(installDirectory)/enrollment.sh" --preview
        Remove the test copy with: sudo "\(installDirectory)/uninstall.sh"

        Task files in framework/tasks/ contain only data (quoted variable assignments). All behavior lives in
        framework/lib/. Logs: \(logDirectory)/
        """
    }
}
